insert into public.faqs(group_en,group_ar,q_en,q_ar,a_en,a_ar,sort) values ('About Maryam and macro photography','عن مريم وتصوير الماكرو','Who is Maryam Aalali?','من هي مريم آل علي؟','Maryam Aalali is a talented Emirati macro photographer who documents the biodiversity of the UAE. She photographs insects, spiders and other small creatures in their own habitat, and shares that work through exhibitions, exploration trips and educational workshops.','مريم آل علي مصورة إماراتية موهوبة متخصصة في تصوير الماكرو، توثّق التنوع البيولوجي في دولة الإمارات. تصوّر الحشرات والعناكب والكائنات الصغيرة في بيئتها الطبيعية، وتشارك أعمالها من خلال المعارض والرحلات الاستكشافية والورش التعليمية.',0);
insert into public.faqs(group_en,group_ar,q_en,q_ar,a_en,a_ar,sort) values ('About Maryam and macro photography','عن مريم وتصوير الماكرو','What is macro photography?','ما هو تصوير الماكرو؟','Macro photography captures very small subjects at life size or larger, so details the eye cannot see become visible: the scales on a butterfly wing, the eyes of a jumping spider, the hairs on a bee.','تصوير الماكرو هو تصوير الأشياء الصغيرة جداً بحجمها الحقيقي أو أكبر، لتظهر تفاصيل لا تراها العين المجردة: حراشف جناح الفراشة، وعيون العنكبوت القافز، وشعيرات النحلة.',1);
insert into public.faqs(group_en,group_ar,q_en,q_ar,a_en,a_ar,sort) values ('About Maryam and macro photography','عن مريم وتصوير الماكرو','Which insects and creatures does Maryam photograph in the UAE?','ما الحشرات والكائنات التي تصوّرها مريم في الإمارات؟','Her gallery includes butterflies and moths, honeybees and solitary bees, wasps, jumping and lynx spiders, mantises, lacewings, grasshoppers and antlions, all photographed in the UAE.','يضم معرضها الفراشات والعث، ونحل العسل والنحل الانفرادي، والدبابير، والعناكب القافزة وعناكب الوشق، وفرس النبي، وأسد المنّ، والجنادب، وأسد النمل، وجميعها مصوّرة في دولة الإمارات.',2);
insert into public.faqs(group_en,group_ar,q_en,q_ar,a_en,a_ar,sort) values ('About Maryam and macro photography','عن مريم وتصوير الماكرو','Why does local documentation of biodiversity matter?','لماذا يهم التوثيق المحلي للتنوع البيولوجي؟','Small creatures pollinate plants, recycle nutrients and feed other wildlife, yet they are rarely noticed or recorded. Documenting them locally builds a visual record of UAE nature and helps people value what lives around them.','تلقّح الكائنات الصغيرة النباتات وتعيد تدوير العناصر الغذائية وتشكّل غذاءً لكائنات أخرى، ومع ذلك نادراً ما تُلاحظ أو تُوثّق. التوثيق المحلي يبني سجلاً بصرياً لطبيعة الإمارات ويساعد الناس على تقدير ما يعيش من حولهم.',3);
insert into public.faqs(group_en,group_ar,q_en,q_ar,a_en,a_ar,sort) values ('Trips and workshops','الرحلات والورش','What happens on an exploration trip?','ماذا يحدث في الرحلة الاستكشافية؟','Exploration trips are guided walks for small groups. Maryam shows participants how to find, observe and photograph insects and spiders. Day trips focus on habitat and patience; night trips use torches and diffused flash to find species that appear after dark.','الرحلات الاستكشافية جولات بإرشاد لمجموعات صغيرة، تعلّم فيها مريم المشاركين كيف يجدون الحشرات والعناكب ويراقبونها ويصوّرونها. تركّز الرحلات النهارية على البيئة والصبر، وتستعين الرحلات الليلية بالمصابيح والفلاش الموزّع لاكتشاف كائنات لا تظهر إلا بعد حلول الظلام.',4);
insert into public.faqs(group_en,group_ar,q_en,q_ar,a_en,a_ar,sort) values ('Trips and workshops','الرحلات والورش','Do you organise trips for children?','هل تنظّمين رحلات للأطفال؟','Yes. Children''s trips and workshops introduce young explorers to nature with magnifying glasses, printed macro photographs and simple field observation. Schools and families can book a session through the contact page.','نعم. رحلات الأطفال والورش التعليمية تعرّف المستكشفين الصغار بالطبيعة باستخدام العدسات المكبّرة وصور الماكرو المطبوعة والملاحظة الميدانية البسيطة. يمكن للمدارس والعائلات حجز جلسة عبر صفحة التواصل.',5);
insert into public.faqs(group_en,group_ar,q_en,q_ar,a_en,a_ar,sort) values ('Trips and workshops','الرحلات والورش','Do you offer educational photography workshops?','هل تقدّمين ورشاً تعليمية للتصوير؟','Yes. Workshops cover how to observe small subjects, approach them without disturbing them, and photograph them with care. Content is adapted to the group, from children to adults.','نعم. تتناول الورش التعليمية للتصوير كيفية ملاحظة الكائنات الصغيرة والاقتراب منها دون إزعاجها وتصويرها بعناية، ويُكيَّف المحتوى حسب المجموعة، من الأطفال إلى الكبار.',6);
insert into public.faqs(group_en,group_ar,q_en,q_ar,a_en,a_ar,sort) values ('Trips and workshops','الرحلات والورش','Do I need a professional camera to join?','هل أحتاج إلى كاميرا احترافية للمشاركة؟','Children''s sessions use magnifiers and printed photographs, so no camera is needed. For photography-focused trips, ask about equipment when you book and Maryam will advise.','لا تحتاج جلسات الأطفال إلى كاميرا، إذ تُستخدم العدسات المكبّرة والصور المطبوعة. أما الرحلات المخصصة للتصوير، فاسأل عن المعدات عند الحجز وستقدّم لك مريم النصيحة.',7);
insert into public.faqs(group_en,group_ar,q_en,q_ar,a_en,a_ar,sort) values ('Trips and workshops','الرحلات والورش','Where do the trips take place?','أين تُقام الرحلات؟','Trips take place in natural areas in the UAE, from woodland to desert. The meeting point is confirmed for each trip when you book.','تُقام الرحلات في مناطق طبيعية داخل دولة الإمارات، من الغابات إلى الصحراء، ويُؤكَّد مكان اللقاء لكل رحلة عند الحجز.',8);
insert into public.faqs(group_en,group_ar,q_en,q_ar,a_en,a_ar,sort) values ('Prints, exhibitions and booking','المطبوعات والمعارض والحجز','Can I buy prints of Maryam''s photographs?','هل يمكنني شراء مطبوعات من صور مريم؟','Yes. Select a photograph from the gallery and send an inquiry with its catalogue number, for example No. 01.','نعم. اختر صورة من المعرض وأرسل استفساراً يتضمن رقمها، مثل رقم 01.',9);
insert into public.faqs(group_en,group_ar,q_en,q_ar,a_en,a_ar,sort) values ('Prints, exhibitions and booking','المطبوعات والمعارض والحجز','Can Maryam exhibit at our school, venue or event?','هل يمكن لمريم إقامة معرض في مدرستنا أو مكاننا أو فعاليتنا؟','Yes. Her outdoor print displays work well in schools, parks, cultural venues and community events. Share your dates and space in an inquiry.','نعم. تناسب معارضها الخارجية المدارس والحدائق والمراكز الثقافية والفعاليات المجتمعية. شارك التواريخ وطبيعة المكان في استفسارك.',10);
insert into public.faqs(group_en,group_ar,q_en,q_ar,a_en,a_ar,sort) values ('Prints, exhibitions and booking','المطبوعات والمعارض والحجز','How do I book a trip or workshop?','كيف أحجز رحلة أو ورشة؟','Open the Book a trip page, choose an available date in the calendar, transfer the fee and upload the receipt with your details. For private groups or schools, use the contact page or WhatsApp +971 52 913 7373.','افتح صفحة احجز رحلة، واختر موعداً متاحاً من التقويم، ثم حوّل الرسوم وارفع الإيصال مع بياناتك. للمجموعات الخاصة والمدارس، استخدم صفحة التواصل أو واتساب ‎+971 52 913 7373‎.',11);
insert into public.gallery(image_url,thumb_url,name_en,name_ar,taxon,taxon_italic,category,alt_en,alt_ar,sort) values ('img/jumping-spider-eyes-macro-uae.jpg','img/thumbs/jumping-spider-eyes-macro-uae.jpg','Jumping spider','عنكبوت قافز','Salticidae',false,'spiders','A jumping spider''s large front eyes in extreme close-up, macro photography of UAE biodiversity by Maryam Aalali','عيون العنكبوت القافز الأمامية عن قرب شديد، تصوير ماكرو للتنوع البيولوجي في الإمارات بعدسة مريم آل علي',0);
