insert into public.gallery(image_url,thumb_url,name_en,name_ar,taxon,taxon_italic,category,alt_en,alt_ar,sort) values ('img/pierrot-butterfly-macro-uae.jpg','img/thumbs/pierrot-butterfly-macro-uae.jpg','Pierrot butterfly','فراشة البييرو','Lycaenidae',false,'butterflies','Pierrot butterfly with striped wings on a dry seed head, macro documentation of UAE insects by Maryam Aalali','فراشة البييرو بأجنحتها المخططة على نبتة جافة، توثيق ماكرو لحشرات الإمارات بعدسة مريم آل علي',2);
insert into public.gallery(image_url,thumb_url,name_en,name_ar,taxon,taxon_italic,category,alt_en,alt_ar,sort) values ('img/green-lacewing-macro-uae.jpg','img/thumbs/green-lacewing-macro-uae.jpg','Green lacewing','أسد المنّ الأخضر','Chrysopidae',false,'other','Green lacewing with transparent veined wings, a beneficial insect photographed in the UAE by Maryam Aalali','أسد المنّ الأخضر بأجنحته الشفافة، حشرة نافعة من بيئة الإمارات بعدسة مريم آل علي',3);
insert into public.gallery(image_url,thumb_url,name_en,name_ar,taxon,taxon_italic,category,alt_en,alt_ar,sort) values ('img/conehead-mantis-macro-uae.jpg','img/thumbs/conehead-mantis-macro-uae.jpg','Conehead mantis','فرس النبي المخروطي','Empusidae',false,'other','Conehead mantis at night with raised forelegs, UAE wildlife macro photograph by Maryam Aalali','فرس النبي المخروطي ليلاً رافعاً قائمتيه الأماميتين، صورة ماكرو للحياة البرية في الإمارات بعدسة مريم آل علي',4);
insert into public.gallery(image_url,thumb_url,name_en,name_ar,taxon,taxon_italic,category,alt_en,alt_ar,sort) values ('img/butterfly-chrysalis-macro-uae.jpg','img/thumbs/butterfly-chrysalis-macro-uae.jpg','Chrysalis','خادرة فراشة','Lepidoptera',false,'butterflies','Butterfly chrysalis hanging from a twig, documenting the butterfly life cycle in the UAE, by Maryam Aalali','خادرة فراشة معلقة على غصن، توثيق لدورة حياة الفراشات في الإمارات بعدسة مريم آل علي',5);
insert into public.gallery(image_url,thumb_url,name_en,name_ar,taxon,taxon_italic,category,alt_en,alt_ar,sort) values ('img/pierid-butterfly-macro-uae.jpg','img/thumbs/pierid-butterfly-macro-uae.jpg','Pierid butterfly','فراشة صفراء','Pieridae',false,'butterflies','Pierid butterfly with pale green eyes on a grass seed head, macro photograph from the UAE by Maryam Aalali','فراشة صفراء بعيون خضراء فاتحة على سنبلة عشب، صورة ماكرو من الإمارات بعدسة مريم آل علي',6);
insert into public.gallery(image_url,thumb_url,name_en,name_ar,taxon,taxon_italic,category,alt_en,alt_ar,sort) values ('img/honeybee-feeding-macro-uae.jpg','img/thumbs/honeybee-feeding-macro-uae.jpg','Honeybee feeding','نحلة عسل تتغذى','Apis',true,'bees','Honeybee feeding with its tongue extended, close-up macro of bees in the UAE by Maryam Aalali','نحلة عسل تتغذى ولسانها ممدود، صورة ماكرو قريبة للنحل في الإمارات بعدسة مريم آل علي',7);
insert into public.gallery(image_url,thumb_url,name_en,name_ar,taxon,taxon_italic,category,alt_en,alt_ar,sort) values ('img/jumping-spider-leaf-macro-uae.jpg','img/thumbs/jumping-spider-leaf-macro-uae.jpg','Jumping spider','عنكبوت قافز','Salticidae',false,'spiders','Small jumping spider peeking from behind a green stem, macro photograph by Emirati photographer Maryam Aalali','عنكبوت قافز صغير يطل من خلف ساق خضراء، صورة ماكرو للمصورة الإماراتية مريم آل علي',8);
insert into public.gallery(image_url,thumb_url,name_en,name_ar,taxon,taxon_italic,category,alt_en,alt_ar,sort) values ('img/grasshopper-macro-uae.jpg','img/thumbs/grasshopper-macro-uae.jpg','Grasshopper','جندب','Orthoptera',false,'other','Front view of a grasshopper''s face and compound eyes, macro insect photography in the UAE by Maryam Aalali','وجه جندب وعيونه المركبة من الأمام، تصوير ماكرو للحشرات في الإمارات بعدسة مريم آل علي',9);
insert into public.gallery(image_url,thumb_url,name_en,name_ar,taxon,taxon_italic,category,alt_en,alt_ar,sort) values ('img/plain-tiger-butterfly-macro-uae.jpg','img/thumbs/plain-tiger-butterfly-macro-uae.jpg','Plain tiger','فراشة النمر','Danaus chrysippus',true,'butterflies','Plain tiger butterfly (Danaus chrysippus) resting on a leafy stem, macro photograph by Emirati photographer Maryam Aalali in the UAE','فراشة النمر على غصن أخضر، صورة ماكرو للمصورة الإماراتية مريم آل علي في دولة الإمارات',10);
insert into public.gallery(image_url,thumb_url,name_en,name_ar,taxon,taxon_italic,category,alt_en,alt_ar,sort) values ('img/sand-wasp-macro-uae.jpg','img/thumbs/sand-wasp-macro-uae.jpg','Sand wasp','دبور الرمل','Hymenoptera',false,'bees','Sand wasp digging its burrow in sand, documenting insect behaviour in the UAE, by Maryam Aalali','دبور الرمل يحفر جحره في الرمال، توثيق لسلوك الحشرات في الإمارات بعدسة مريم آل علي',11);
insert into public.gallery(image_url,thumb_url,name_en,name_ar,taxon,taxon_italic,category,alt_en,alt_ar,sort) values ('img/moth-fly-macro-uae.jpg','img/thumbs/moth-fly-macro-uae.jpg','Moth fly','ذبابة العُث','Psychodidae',false,'other','Moth fly with fringed, feather-like wings seen from above, macro photograph by Maryam Aalali','ذبابة العُث بأجنحتها الريشية من الأعلى، صورة ماكرو بعدسة مريم آل علي',12);
insert into public.gallery(image_url,thumb_url,name_en,name_ar,taxon,taxon_italic,category,alt_en,alt_ar,sort) values ('img/swallowtail-wing-scales-macro.jpg','img/thumbs/swallowtail-wing-scales-macro.jpg','Swallowtail wing scales','حراشف جناح ذيل السنونو','Papilionidae',false,'butterflies','Swallowtail butterfly wing scales in extreme macro, showing colour patterns invisible to the naked eye, by Maryam Aalali','حراشف جناح فراشة ذيل السنونو بتكبير شديد تكشف ألواناً لا تراها العين المجردة، بعدسة مريم آل علي',13);
insert into public.gallery(image_url,thumb_url,name_en,name_ar,taxon,taxon_italic,category,alt_en,alt_ar,sort) values ('img/lynx-spider-macro-uae.jpg','img/thumbs/lynx-spider-macro-uae.jpg','Lynx spider','عنكبوت الوشق','Oxyopidae',false,'spiders','Green lynx spider on dry flowers, spider macro photography from the UAE by Maryam Aalali','عنكبوت الوشق الأخضر على أزهار جافة، تصوير ماكرو للعناكب في الإمارات بعدسة مريم آل علي',14);
insert into public.gallery(image_url,thumb_url,name_en,name_ar,taxon,taxon_italic,category,alt_en,alt_ar,sort) values ('img/solitary-bee-macro-uae.jpg','img/thumbs/solitary-bee-macro-uae.jpg','Solitary bee at rest','نحلة انفرادية تستريح','Apidae',false,'bees','Solitary bee with green eyes resting on a stem, bee macro photograph from the UAE by Maryam Aalali','نحلة انفرادية بعيون خضراء تستريح على ساق نبتة، صورة ماكرو للنحل في الإمارات بعدسة مريم آل علي',15);
insert into public.gallery(image_url,thumb_url,name_en,name_ar,taxon,taxon_italic,category,alt_en,alt_ar,sort) values ('img/antlion-macro-uae.jpg','img/thumbs/antlion-macro-uae.jpg','Antlion','أسد النمل','Myrmeleontidae',false,'other','Antlion with clubbed antennae perched on a stem, macro photograph by Emirati photographer Maryam Aalali','أسد النمل بقرون استشعار معقوفة على ساق نبتة، صورة ماكرو للمصورة الإماراتية مريم آل علي',16);
insert into public.gallery(image_url,thumb_url,name_en,name_ar,taxon,taxon_italic,category,alt_en,alt_ar,sort) values ('img/honeybee-comb-macro-uae.jpg','img/thumbs/honeybee-comb-macro-uae.jpg','Honeybee on the comb','نحلة على القرص','Apis',true,'bees','Honeybee standing on the honeycomb, from Maryam Aalali''s bee documentation series in the UAE','نحلة عسل على أقراص الشمع، من سلسلة توثيق النحل للمصورة مريم آل علي في الإمارات',17);
insert into public.gallery(image_url,thumb_url,name_en,name_ar,taxon,taxon_italic,category,alt_en,alt_ar,sort) values ('img/butterfly-wing-scales-macro.jpg','img/thumbs/butterfly-wing-scales-macro.jpg','Wing scales','حراشف الجناح','Lepidoptera',false,'butterflies','Iridescent blue butterfly wing scales in macro, by Maryam Aalali','حراشف جناح فراشة زرقاء متلألئة بتصوير الماكرو، بعدسة مريم آل علي',18);
insert into public.gallery(image_url,thumb_url,name_en,name_ar,taxon,taxon_italic,category,alt_en,alt_ar,sort) values ('img/honeybees-hive-macro-uae.jpg','img/thumbs/honeybees-hive-macro-uae.jpg','Honeybees at work','نحل في الخلية','Apis',true,'bees','Two honeybees working on the comb cells, macro photograph from Maryam Aalali''s bee series','نحلتان تعملان على خلايا القرص، صورة ماكرو من سلسلة النحل لمريم آل علي',19);
insert into public.trips(kind,title_en,title_ar,trip_date,start_time,end_time,location_en,location_ar,price_aed,capacity,includes_en,includes_ar,rules_en,rules_ar,published) values ('macro_walk','Macro Walk','جولة ماكرو','2026-04-04','09:00',null,'Mushrif Park, Dubai','حديقة مشرف، دبي',150,15,array['Macro photos for learning & discussion before the walk','Interactive exploration challenge during the walk','Drinks & snacks','Headlamps','Full trip guidance experience']::text[],array['صور ماكرو للتعلّم والنقاش قبل الجولة','تحدٍّ استكشافي تفاعلي خلال الجولة','مشروبات ووجبات خفيفة','مصابيح رأس','تجربة إرشاد كاملة طوال الرحلة']::text[],'I commit to respecting nature, keeping the area clean and following Mushrif Park rules, and I understand that each participant is responsible for their own safety during the walk.','ألتزم باحترام الطبيعة والحفاظ على نظافة المكان واتباع أنظمة حديقة مشرف، وأدرك أن كل مشارك مسؤول عن سلامته الشخصية خلال الجولة.',false);
